package com.bank.instalment.service;

import java.util.logging.Logger;

// Count distinct 1-or-2 unit payment sequences: Fibonacci-style DP.
public class InstalmentPlanService {
    private static final Logger log = Logger.getLogger(InstalmentPlanService.class.getName());

    public long countPaymentSequences(int units) {
        if (units < 0) throw new IllegalArgumentException("units must be >= 0");
        if (units <= 1) return 1;                         // one way for 0 or 1 unit
        long twoBelow = 1, oneBelow = 1;                  // ways to finish 0 and 1 unit
        for (int i = 2; i <= units; i++) {
            long cur = oneBelow + twoBelow;               // last move: 1-unit or 2-unit
            twoBelow = oneBelow;                          // roll the window forward
            oneBelow = cur;
        }
        final long result = oneBelow;
        log.info(() -> "Distinct payment sequences for " + units + " units = " + result);
        return oneBelow;
    }
}
